// Build one CTE that creates the recruiter, the pending outreach, and the
// approval token atomically, returning the token for the notification email.
function q(s){ return String(s==null?'':s).replace(/'/g, "''"); }
const app = $('Get Ready Applications').item.json;
let contact = {}; try { contact = JSON.parse($('Extract Contact').item.json.response || '{}'); } catch(e) {}
let mail = {}; const mr = $('Generate Outreach').item.json.response || '';
try { mail = JSON.parse(mr); } catch(e) { const m = mr.match(/\{[\s\S]*\}/); if (m) { try { mail = JSON.parse(m[0]); } catch(_){} } }
const email = (contact && contact.email && /.+@.+\..+/.test(contact.email)) ? contact.email : null;
const subject = mail.subject || ('Interest in the ' + app.title + ' role');
const body = mail.body || '';
const conf = email ? 0.6 : 0.0;
const recVals = `(${contact && contact.name ? `'${q(contact.name)}'` : 'NULL'}, ${email ? `'${q(email)}'` : 'NULL'}, '${q(app.company_name)}', ${contact && contact.title ? `'${q(contact.title)}'` : 'NULL'}, 'public-page', ${conf})`;
const query = `WITH rec AS (INSERT INTO app.recruiters (full_name,email,company_name,title,source,confidence) VALUES ${recVals} RETURNING id), o AS (INSERT INTO app.outreach (application_id, recruiter_id, subject, body, status) SELECT '${app.app_id}', rec.id, '${q(subject)}', '${q(body)}', 'pending_approval' FROM rec RETURNING id), ap AS (INSERT INTO app.approvals (entity_type, entity_id, action, payload) SELECT 'outreach', o.id, 'send_email', '{}'::jsonb FROM o RETURNING entity_id, token) SELECT ap.token AS token, ap.entity_id AS outreach_id FROM ap;`;
return [{ json: { query, subject, body, recruiter_email: email } }];

